mapper.select:
SELECT id, scope_type AS scopeType, scope_ref AS scopeRef, workspace_id AS workspaceId, exported_by AS exportedBy, exported_at AS exportedAt, clearance, include_confidential AS includeConfidential, omitted_sections AS omittedSections, file_count AS fileCount, row_count AS rowCount, package_hash AS packageHash, signature_alg AS signatureAlg, key_id AS keyId, signature, create_at AS createAt, update_at AS updateAt, create_by AS createBy, update_by AS updateBy, deleted FROM evidence_pack WHERE scope_type = #{scopeType} AND scope_ref = #{scopeRef} AND deleted = false
AND workspace_id = #{workspaceId}
ORDER BY exported_at DESC, id DESC LIMIT #{limit}
